// marimo: follows the live marimo notebook open under the project.
//
// - Status line under the prompt: `marimo: fit.py · running Data loading › Model fit (12s) · 1 error`.
// - Context: each prompt carries the notebook's current state beside it (prompt.submit's context).
//   Older copies are left out of every later request (prompt.attachment answers null for them),
//   so the conversation holds one copy, the latest, instead of one per prompt.
// - /marimo: status, show, auto, off, or a notebook path to follow.
// - herdr: when a turn ends with a cell Claude started still running, the pane token `marimo`
//   says what runs until the kernel goes quiet, then a notification says it finished.
//
// The port of pi-marimo; core/ is shared with it unchanged. The host reads on(...) and
// $.noun.method(...) from source, so every $ call is spelled in full in this file and the
// core reaches the host only through the Io built in claudeIo.
import type { EngineInterface, On } from 'claude-code'

import { HERDR_SOURCE, HERDR_TOKEN, type HoldChange, KernelHold } from './core/hold.js'
import { type Cancellable, type Io, normalize, type StreamEnd } from './core/io.js'
import { type SnapshotEntry, snapshot, STATE_TAG, statusParts, statusText } from './core/render.js'
import { pairTargets } from './core/touch.js'
import { MarimoWatcher, type Mode } from './core/watcher.js'

const COMMAND = 'marimo'

/** What the hooks share across a session. */
interface State {
  watcher?: MarimoWatcher
  /** Browser edits after this change number are flagged as new in the next prompt's state. */
  /** Per notebook path: browser edits after this change number are flagged as new in the next state. */
  seen: Map<string, number>
  /** Revisions of the state this process attached are `<nonce>-<n>`; only the latest is kept. */
  nonce: string
  revision: number
  ticker?: { cancel: () => void }
  lastStatus?: string
  /** A cell Claude started that outlives its turn, shown in herdr. */
  hold: KernelHold
  /** herdr reports, in order. */
  herdr: Promise<unknown>
  /** Whether the `marimo` token is set. */
  holding: boolean
}

export function register(on: On): void {
  const s: State = { seen: new Map(), nonce: Math.random().toString(36).slice(2, 8), revision: 0, hold: new KernelHold(), herdr: Promise.resolve(), holding: false }

  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await $.command.register({
      name: COMMAND,
      description: 'marimo: status, show, auto, off, or a notebook path to follow',
      argumentHint: '[status|show|auto|off|<path>]',
      immediate: true,
    })
    const cwd = await $.session.cwd()
    const token = (await $.env.get('MARIMO_TOKEN'))?.trim() || undefined
    const pinned = (await $.env.get('MARIMO_NOTEBOOK'))?.trim()
    startWatcher($, s, cwd, token, pinned)
    return started
  })

  on('session.end', async ($, e, next) => {
    await herdr($, s, s.hold.release())
    s.ticker?.cancel()
    s.ticker = undefined
    await s.watcher?.stop()
    s.watcher = undefined
    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    const watcher = s.watcher
    if (!watcher) return next(e)
    watcher.refresh()
    await watcher.settle(2000)
    const entries = stateEntries(watcher, s)
    if (!entries.length) return next(e)
    s.revision++
    const text = stateText(entries, `${s.nonce}-${s.revision}`)
    const result = await next({ ...e, context: [...(e.context ?? []), text] })
    // Ask every attachment again, so the copies this one supersedes are left out.
    $.ui.invalidate('prompt.attachment')
    return result
  })

  on('prompt.attachment', ($, e, next) => {
    if (e.origin.kind === 'plugin' && isStaleState(e.text, `${s.nonce}-${s.revision}`)) return { text: null }
    return next(e)
  })

  // The notebook this session's agent works in (through marimo-pair) becomes current for it,
  // whatever other sessions or the browser do; subagents' calls count as this session's.
  on('tool.call', ($, e, next) => {
    const targets = pairTargets(JSON.stringify(e))
    if (targets.length) s.watcher?.touch(targets)
    return next(e)
  })

  on('turn.start', ($, e, next) => {
    void herdr($, s, s.hold.begin(Date.now()))
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId !== undefined) return next(e)
    const followed = s.watcher?.followed() ?? []
    for (const f of followed) s.seen.set(f.attachment.path, f.notebook.seq)
    void herdr($, s, s.hold.end(followed, Date.now()))
    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    const watcher = s.watcher
    if (!watcher) return { text: 'marimo: not started' }
    const arg = e.args.trim()
    if (arg === 'auto' || arg === 'off') {
      watcher.setMode(modeFor(arg === 'off' ? 'off' : undefined))
      return { text: arg === 'off' ? 'marimo: off' : 'marimo: following every notebook open under this directory' }
    }
    if (arg === 'show') {
      const entries = stateEntries(watcher, s)
      return { text: entries.length ? snapshot(entries, { refresh: 'prompt' }) : statusFor(watcher) ?? 'marimo: no notebook attached' }
    }
    if (arg && arg !== 'status') {
      const cwd = await $.session.cwd()
      const paths = arg.split(/[\s,]+/).filter(Boolean).map((p) => normalize(p, cwd))
      watcher.setMode({ kind: 'pinned', paths })
      return { text: `marimo: following ${paths.join(', ')}` }
    }
    const open = await watcher.list()
    return {
      text: [
        statusFor(watcher) ?? 'marimo: no notebook attached',
        `Mode: ${watcher.mode.kind}${watcher.mode.kind === 'pinned' ? ` (${watcher.mode.paths.join(', ')})` : ''}.`,
        open.length ? `Open notebooks:\n${open.map((n) => `  ${n.path}  (${n.url}, session ${n.sessionId})`).join('\n')}` : 'No marimo notebooks are open.',
      ].join('\n'),
    }
  })

}

function startWatcher($: EngineInterface, s: State, cwd: string, token: string | undefined, pinned: string | undefined): void {
  s.watcher = new MarimoWatcher({ io: claudeIo($), cwd, token, onChange: () => showStatus($, s) })
  s.watcher.mode = modeFor(pinned)
  s.watcher.start()
}

/** Pin the status line; tick it every second while a cell runs. */
function showStatus($: EngineInterface, s: State): void {
  const watcher = s.watcher
  if (!watcher) return
  if (s.hold.active) void herdr($, s, s.hold.update(watcher.followed(), Date.now()))
  const text = statusFor(watcher)
  if (text !== s.lastStatus) {
    s.lastStatus = text
    // The host labels a plugin's status line with the plugin's name ("marimo: ").
    $.ui.status(text?.replace(/^marimo: /, ''))
  }
  const running = watcher.connection === 'connected' && watcher.notebook.running()
  if (running && !s.ticker) s.ticker = $.clock.every(1000, () => showStatus($, s))
  if (!running && s.ticker) {
    s.ticker.cancel()
    s.ticker = undefined
  }
}

/**
 * The herdr CLI calls for a hold change. herdr's Claude integration only reports the session and
 * herdr reads Claude Code's state from the screen; it takes no state from any other reporter once
 * that session is known, so the pane stays `idle`. While held, the pane token `marimo` says what
 * runs; when the run ends it is cleared, and a notification follows unless the pane is focused.
 */
export function herdrCalls(change: HoldChange, pane: string, reported: boolean): string[][] {
  const metadata = ['herdr', 'pane', 'report-metadata', pane, '--source', HERDR_SOURCE, '--agent', 'claude']
  if (change.kind === 'none') return []
  if (change.kind === 'held') return [[...metadata, '--token', `${HERDR_TOKEN}=${change.value}`, '--ttl-ms', '86400000']]
  return reported ? [[...metadata, '--clear-token', HERDR_TOKEN]] : []
}

/** Report a hold change to herdr, inside a herdr pane only; any failure is ignored. */
function herdr($: EngineInterface, s: State, change: HoldChange): Promise<unknown> {
  if (change.kind === 'none') return s.herdr
  s.herdr = s.herdr.then(async () => {
    if ((await $.env.get('HERDR_ENV')) !== '1') return
    const pane = await $.env.get('HERDR_PANE_ID')
    if (!pane) return
    const calls = herdrCalls(change, pane, s.holding)
    s.holding = change.kind === 'held'
    for (const argv of calls) await $.process.run(argv, { timeoutMs: 3_000 }).catch(() => undefined)
    if (change.kind !== 'finished') return
    const got = await $.process.run(['herdr', 'pane', 'get', pane], { timeoutMs: 3_000 }).catch(() => undefined)
    if (got && got.exitCode === 0 && /"focused":true/.test(got.stdout)) return
    await $.process.run(['herdr', 'notification', 'show', change.title, '--body', change.body, '--sound', 'done'], { timeoutMs: 3_000 }).catch(() => undefined)
  }).catch(() => undefined)
  return s.herdr
}

/**
 * MARIMO_NOTEBOOK=<path>[,<path>...] follows those notebooks, =off turns the mod off; unset follows
 * every notebook open under the project.
 */
export function modeFor(pinned: string | undefined): Mode {
  if (pinned === 'off') return { kind: 'off' }
  const paths = (pinned ?? '').split(',').map((p) => p.trim()).filter(Boolean)
  return paths.length ? { kind: 'pinned', paths } : { kind: 'auto' }
}

/** The followed notebooks that are connected, the current one first. */
export function stateEntries(watcher: MarimoWatcher, s: { seen: Map<string, number> }) {
  return watcher.followed()
    .filter((f) => f.connection === 'connected' && f.notebook.ready)
    .map((f) => ({ notebook: f.notebook, attachment: f.attachment, current: f.current, seenSeq: s.seen.get(f.attachment.path) ?? 0 }))
}

export function statusFor(watcher: MarimoWatcher): string | undefined {
  const { connection, attachment, mode } = watcher
  if (!attachment) return undefined
  if (connection === 'searching') {
    return mode.kind === 'pinned' ? statusText({ notebook: mode.paths.map((p) => p.split('/').pop()).join(', '), connection: 'not open', queued: 0, errors: 0 }) : undefined
  }
  return statusText(statusParts(watcher.notebook, attachment, connection, Date.now(), watcher.others()))
}

/** The state block, tagged with its revision so later requests can tell it is superseded. */
export function stateText(entries: SnapshotEntry[], rev: string): string {
  return snapshot(entries, { refresh: 'prompt' }).replace(`<${STATE_TAG} `, `<${STATE_TAG} rev="${rev}" `)
}

/** True for a state block of this plugin that is not the latest revision. */
export function isStaleState(text: string, latest: string): boolean {
  const match = new RegExp(`<${STATE_TAG} rev="([^"]+)"`).exec(text)
  return match !== null && match[1] !== latest
}

/** The core's host calls, through $: no Node APIs in a mod's sandbox. */
function claudeIo($: EngineInterface): Io {
  return {
    async registryEntries() {
      const home = (await $.env.get('HOME')) ?? ''
      const state = (await $.env.get('XDG_STATE_HOME')) || `${home}/.local/state`
      const dir = `${state}/marimo/servers`
      const entries: unknown[] = []
      const files = await $.fs.list(dir).catch(() => [])
      for (const file of files) {
        if (file.kind !== 'file' || !file.name.endsWith('.json')) continue
        try {
          entries.push(JSON.parse(await $.fs.read(`${dir}/${file.name}`)))
        } catch {
          // A file being written or removed; skip it this round.
        }
      }
      return entries
    },

    async getJson(url, headers, timeoutMs) {
      const request = $.http.fetch(url, { headers }).then(
        (response) => (response.ok ? JSON.parse(response.text) : undefined),
        () => undefined,
      )
      const timeout = $.clock.sleep(timeoutMs).then(() => undefined)
      return Promise.race([request, timeout]).catch(() => undefined)
    },

    // $.http.fetch buffers a whole body, so the SSE stream is read through curl.
    stream(url, headers, onText): Cancellable<StreamEnd> {
      const argv = ['curl', '--silent', '--no-buffer', '--fail']
      for (const [name, value] of Object.entries(headers)) argv.push('--header', `${name}: ${value}`)
      argv.push(url)
      const child = $.process.spawn({ argv })
      let received = false
      let cancelled = false
      const done = (async (): Promise<StreamEnd> => {
        try {
          for await (const chunk of child) {
            if (cancelled) break
            if (chunk.stream !== 'stdout') continue
            received = true
            onText(chunk.text)
          }
        } catch {
          return { ok: cancelled }
        }
        return { ok: received || cancelled }
      })()
      return {
        done,
        cancel: () => {
          cancelled = true
          void child.return(undefined as never).catch(() => undefined)
        },
      }
    },

    async realpath(path) {
      const result = await $.process.run(['realpath', path]).catch(() => undefined)
      const real = result && result.exitCode === 0 ? result.stdout.trim() : ''
      return real || path
    },

    sleep(ms): Cancellable<void> {
      let cancel = (): void => {}
      const done = new Promise<void>((resolve) => {
        const timer = $.clock.after(ms, resolve)
        cancel = () => {
          timer.cancel()
          resolve()
        }
      })
      return { done, cancel }
    },
  }
}

files.hooks/core/hold.ts:
// The kernel hold: the stretch after the agent's turn ends while a cell it
// started is still running. It begins when a turn ends with a notebook the agent
// worked in during that turn busy (a cell running or queued), and ends when
// every held notebook is quiet, disconnected or no longer followed, or when the
// next turn begins. The hosts show it in herdr; this file only decides it.

import { basename } from "./io.js";
import { truncate } from "./notebook.js";
import { elapsed } from "./render.js";
import type { Followed } from "./watcher.js";

/** The herdr pane token the ports report while the kernel holds (`$marimo` in a sidebar row). */
export const HERDR_TOKEN = "marimo";
/** The herdr metadata source the ports report under. */
export const HERDR_SOURCE = "marimo";

export type HoldChange =
  | { kind: "none" }
  /** The hold began, or what it shows changed. */
  | { kind: "held"; value: string }
  /** The hold ended because the kernel went quiet; what to tell the user. */
  | { kind: "finished"; title: string; body: string }
  /** The hold ended without the kernel finishing (a new turn, the session ending). */
  | { kind: "released" };

const NONE: HoldChange = { kind: "none" };

export function busy(f: Followed): boolean {
  return f.connection === "connected" && (f.notebook.running() !== undefined || f.notebook.queued() > 0);
}

/** What the pane token says: `fit.py: Model fit`, `fit.py: cell train`, or `fit.py: 3 queued`. */
export function holdValue(f: Followed): string {
  const file = basename(f.attachment.path);
  const run = f.notebook.running();
  if (!run) return `${file}: ${f.notebook.queued()} queued`;
  const where = run.section[run.section.length - 1] ?? `cell ${run.cell.name !== "_" ? run.cell.name : run.cell.id}`;
  return truncate(`${file}: ${where}`, 80);
}

export class KernelHold {
  private turnStartedAt: number | undefined;
  private held = new Set<string>();
  private since = 0;
  private last: string | undefined;

  get active(): boolean {
    return this.held.size > 0;
  }

  /** The notebooks held, by path. */
  get paths(): string[] {
    return [...this.held];
  }

  /** A turn began: the agent is working again, so any hold ends. */
  begin(now: number): HoldChange {
    this.turnStartedAt = now;
    return this.release();
  }

  /** The turn ended: hold the busy notebooks the agent worked in during it. */
  end(followed: Followed[], now: number): HoldChange {
    const startedAt = this.turnStartedAt;
    this.turnStartedAt = undefined;
    if (startedAt === undefined || this.active) return NONE;
    for (const f of followed) if (f.touchedAt >= startedAt && busy(f)) this.held.add(f.attachment.path);
    if (!this.active) return NONE;
    this.since = now;
    return this.update(followed, now);
  }

  /** After a notebook changed: what the hold shows now, or that it finished. */
  update(followed: Followed[], now: number): HoldChange {
    if (!this.active) return NONE;
    const held = followed.filter((f) => this.held.has(f.attachment.path));
    const running = held.filter(busy);
    if (!running.length) {
      this.held.clear();
      this.last = undefined;
      const files = held.length ? held.map((f) => basename(f.attachment.path)).join(", ") : "notebook";
      const errors = held.reduce((n, f) => n + (f.connection === "connected" ? f.notebook.errors().length : 0), 0);
      const gone = held.length < 1 || held.some((f) => f.connection !== "connected");
      const parts = [`ran ${elapsed(now - this.since)}`];
      if (errors) parts.push(`${errors} error${errors === 1 ? "" : "s"}`);
      if (gone) parts.push("disconnected");
      return { kind: "finished", title: truncate(`${files} ${gone ? "stopped" : "finished"}`, 80), body: parts.join(" · ") };
    }
    const value = holdValue(running[0]!);
    if (value === this.last) return NONE;
    this.last = value;
    return { kind: "held", value };
  }

  /** Stop holding without a notice. */
  release(): HoldChange {
    if (!this.active) return NONE;
    this.held.clear();
    this.last = undefined;
    return { kind: "released" };
  }
}

