// Text views of a NotebookState: a one-line status for footers and status lines,
// and the compact state block injected into the agent's context.

import { basename } from "./io.js";
import { type Cell, NotebookState, truncate } from "./notebook.js";

export interface Attachment {
  url: string;
  sessionId: string;
  path: string;
}

export const STATE_TAG = "marimo_notebook_state";

export function elapsed(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000));
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m${String(s % 60).padStart(2, "0")}s`;
  return `${Math.floor(m / 60)}h${String(m % 60).padStart(2, "0")}m`;
}

export interface StatusParts {
  notebook: string;
  /** "connected" | "connecting" | "disconnected" */
  connection: string;
  running?: { section: string; cell: string; elapsed?: string };
  queued: number;
  errors: number;
  /** File names of the other notebooks followed, most recently used first. */
  others?: string[];
}

export function statusParts(nb: NotebookState, attachment: Attachment, connection: string, now = Date.now(), others: Attachment[] = []): StatusParts {
  const run = connection === "connected" ? nb.running() : undefined;
  return {
    notebook: basename(attachment.path),
    connection,
    running: run
      ? {
        section: run.section.join(" › "),
        cell: run.cell.name !== "_" ? run.cell.name : run.cell.id,
        elapsed: run.since !== undefined ? elapsed(now - run.since) : undefined,
      }
      : undefined,
    queued: connection === "connected" ? nb.queued() : 0,
    errors: connection === "connected" ? nb.errors().length : 0,
    others: others.map((o) => basename(o.path)),
  };
}

/**
 * One line, e.g. `marimo: fit.py · running Data loading › Model fit (12s) · 2 queued · 1 error · also prep.py, plots.py`.
 * The shape is stable so footers can parse it: `marimo: <current file>`, then ` · ` separated parts
 * about it, then `also <file>, <file>` naming the other notebooks followed.
 */
export function statusText(parts: StatusParts): string {
  const out = [`marimo: ${parts.notebook}`];
  if (parts.connection !== "connected") out.push(parts.connection);
  if (parts.running) {
    const where = parts.running.section || `cell ${parts.running.cell}`;
    out.push(`running ${where}${parts.running.elapsed ? ` (${parts.running.elapsed})` : ""}`);
  }
  if (parts.queued) out.push(`${parts.queued} queued`);
  if (parts.errors) out.push(`${parts.errors} error${parts.errors === 1 ? "" : "s"}`);
  if (parts.others?.length) out.push(`also ${parts.others.join(", ")}`);
  return out.join(" · ");
}

function firstLine(code: string): string {
  const line = code.split("\n").map((l) => l.trim()).find((l) => l && !l.startsWith("#")) ?? "";
  return truncate(line, 60);
}

export interface SnapshotOptions {
  /** When the block is refreshed: before every model request, or once per user prompt. */
  refresh?: "request" | "prompt";
  /** Above this many cells, quiet code cells of the current notebook are folded into counts. */
  maxCells?: number;
  now?: number;
}

export interface SnapshotEntry {
  notebook: NotebookState;
  attachment: Attachment;
  current?: boolean;
  /** Edits from the browser after this change number are flagged as new. */
  seenSeq?: number;
}

interface SectionOptions {
  seen: number;
  now: number;
  maxCells: number;
  /** Deeper headings are left out (for the notebooks that are not current). */
  maxLevel: number;
}

/**
 * One notebook as an outline: headings, then one line per code cell with its
 * id, what it defines, and anything that needs attention.
 */
function section(nb: NotebookState, attachment: Attachment, current: boolean, o: SectionOptions): string[] {
  const { now, seen } = o;
  const cells = nb.ordered();
  const fold = cells.length > o.maxCells;
  // When most cells are stale (a lazy notebook after a restart), say so once instead of on every line.
  const staleCount = cells.filter((c) => c.stale).length;
  const staleCommon = staleCount > cells.length / 2;
  // Likewise a Run all: the queue is counted on the Kernel line, so list queued cells only when few.
  const queuedCount = cells.filter((c) => c.status === "queued").length;
  const queuedCommon = queuedCount > 10 || queuedCount > cells.length / 2;

  const notes = (cell: Cell): string[] => {
    const out: string[] = [];
    if (cell.status === "running") out.push(`RUNNING${cell.runningSince ? ` ${elapsed(now - cell.runningSince)}` : ""}`);
    else if (cell.status === "queued" && !queuedCommon) out.push("queued");
    if (cell.error) out.push(`ERROR ${cell.error}`);
    if (cell.blocked) out.push("not run: an ancestor failed");
    if (cell.disabled) out.push("disabled");
    else if (cell.status === "disabled-transitively") out.push("disabled by an ancestor");
    if (cell.stale && !staleCommon) out.push("stale");
    if (nb.edited(cell)) out.push("edited, not rerun");
    if (cell.editedBy === "frontend" && cell.editSeq > seen) out.push("changed by the user in the browser");
    return out;
  };

  const lines: string[] = [];
  let folded = 0;
  const flushFolded = (): void => {
    if (folded) lines.push(`  … ${folded} more cell${folded === 1 ? "" : "s"}`);
    folded = 0;
  };
  const heading = (level: number, text: string, tail: string): void => {
    if (level <= o.maxLevel) { flushFolded(); lines.push(`${"#".repeat(level)} ${text}${tail}`); }
  };
  for (const cell of cells) {
    const headings = nb.headings(cell);
    const cellNotes = notes(cell);
    if (headings.length && nb.isMarkdown(cell)) {
      headings.forEach((h, i) => heading(h.level, h.text, i === 0 ? `  [${cell.id}]${cellNotes.length ? ` ${cellNotes.join("; ")}` : ""}` : ""));
      if (cellNotes.length && !headings.some((h) => h.level <= o.maxLevel)) { flushFolded(); lines.push(`  ${cell.id} (markdown) ${cellNotes.join("; ")}`); }
      continue;
    }
    if (nb.isMarkdown(cell)) {
      if (cellNotes.length) { flushFolded(); lines.push(`  ${cell.id} (markdown) ${cellNotes.join("; ")}`); }
      else if (fold) folded++;
      else lines.push(`  ${cell.id} (markdown)`);
      continue;
    }
    // Folded or not, the outline keeps every heading (down to maxLevel).
    for (const h of headings) heading(h.level, h.text, `  [${cell.id}]`);
    if (fold && !cellNotes.length) { folded++; continue; }
    flushFolded();
    const defs = nb.defs.get(cell.id) ?? [];
    const label = cell.name !== "_" ? `${cell.id} "${cell.name}"` : cell.id;
    const what = defs.length ? `defines ${truncate(defs.join(", "), 80)}` : firstLine(cell.code) || "(empty)";
    lines.push(`  ${label}: ${what}${cellNotes.length ? ` -- ${cellNotes.join("; ")}` : ""}`);
  }
  flushFolded();

  const run = nb.running();
  const summary: string[] = [];
  if (run) summary.push(`running ${run.cell.id}${run.section.length ? ` under "${run.section.join(" › ")}"` : ""}`);
  const queued = nb.queued();
  if (queued) summary.push(`${queued} queued`);
  const errors = nb.errors().length;
  if (errors) summary.push(`${errors} cell${errors === 1 ? "" : "s"} with errors`);
  if (staleCommon) summary.push(`${staleCount} of ${cells.length} cells stale (inputs changed, not rerun)`);

  return [
    `=== ${attachment.path} (${current ? "current" : "also followed"}; ${attachment.url}, session ${attachment.sessionId}) ===`,
    `Kernel: ${summary.length ? summary.join(", ") : "idle"}.`,
    ...lines,
  ];
}

/**
 * The followed notebooks in one block, the current one (used most recently)
 * first and in full; the others as a short outline (headings down to ##) with
 * the cells that need attention.
 */
export function snapshot(entries: SnapshotEntry[], options: SnapshotOptions = {}): string {
  const now = options.now ?? Date.now();
  const sections = entries.map((e, i) => {
    const current = e.current ?? i === 0;
    return section(e.notebook, e.attachment, current, {
      seen: e.seenSeq ?? Number.POSITIVE_INFINITY,
      now,
      maxCells: current ? options.maxCells ?? 60 : 0,
      maxLevel: current ? 6 : 2,
    });
  });
  const many = entries.length > 1;
  return [
    `<${STATE_TAG} notebooks="${entries.length}">`,
    `Live state of the marimo notebook${many ? "s" : ""} open in the user's browser, added automatically by pi-marimo (not`,
    ...(options.refresh === "prompt"
      ? ["written by the user). Taken when the user sent their latest message and not updated during the turn;",
        "earlier copies are removed. Check current values through marimo-pair before relying on them."]
      : ["written by the user). It is replaced with a fresh copy on every request, so trust this over older reads."]),
    ...(many ? ["The current notebook (the one used most recently) comes first and in full; the others are outlines",
      "with only the cells that need attention."] : []),
    "Cells are listed in notebook order under their markdown headings, by cell id. Inspect or change cells",
    "through the marimo-pair skill, not by editing the .py file.",
    ...sections.flatMap((lines) => ["", ...lines]),
    `</${STATE_TAG}>`,
  ].join("\n");
}

files.hooks/core/touch.ts:
// Which notebooks an agent's tool call works in, read from its marimo-pair
// commands, so each agent session can keep the notebook it works in current
// even while another session (or the user) works in a different one.
//
// marimo-pair runs `execute-code.sh --url URL [--file PATH | --session ID]` or
// `marimo pair execute --url URL [--file FILE] [--session ID]`. A tool call may
// hold several (one bash command, a codemode script), in any quoting.

export interface PairTarget {
  url?: string;
  file?: string;
  session?: string;
}

const CALL = /execute-code\.sh|marimo\s+pair\s+execute/g;

function flag(segment: string, name: string): string | undefined {
  const match = new RegExp(`--${name}(?:=|\\s+)(?:"([^"]+)"|'([^']+)'|([^\\s"'\\\\;|&)]+))`).exec(segment);
  const value = match?.[1] ?? match?.[2] ?? match?.[3];
  // A shell variable or substitution cannot be resolved here.
  return value && !value.includes("$") ? value : undefined;
}

/** The notebooks the marimo-pair calls in a tool call's text target, in order. */
export function pairTargets(raw: string): PairTarget[] {
  // Tool input arrives as JSON too, with its quotes escaped.
  const text = raw.replace(/\\"/g, '"');
  const starts: number[] = [];
  CALL.lastIndex = 0;
  for (let m = CALL.exec(text); m; m = CALL.exec(text)) starts.push(m.index);
  return starts.map((start, i) => {
    const segment = text.slice(start, starts[i + 1] ?? text.length).split(/\n|\\n/)[0] ?? "";
    const target: PairTarget = {};
    const url = flag(segment, "url");
    const file = flag(segment, "file");
    const session = flag(segment, "session");
    if (url) target.url = url;
    if (file) target.file = file;
    if (session) target.session = session;
    return target;
  });
}

/** One server, however it is written (localhost or 127.0.0.1, a trailing slash). */
export function sameServer(a: string, b: string): boolean {
  const norm = (u: string) => u.replace(/\/+$/, "").replace("://localhost", "://127.0.0.1").replace("://[::1]", "://127.0.0.1");
  return norm(a) === norm(b);
}

files.hooks/core/watcher.ts:
// Keeps the live state of the notebooks you work in current. It finds them,
// subscribes to each one's session as a kiosk consumer, follows them across
// page reloads (which change the session id) and server restarts, and reports
// every change. The followed notebooks are the pinned ones, or in auto mode
// every one open under the cwd. The current one is the one this session's agent
// worked in last (through marimo-pair), so two sessions in two notebooks each
// keep their own; before the agent touches any, the one used most recently by
// anyone (a running cell, then the latest cell run or edit).

import { type Cancellable, type Io, normalize, within } from "./io.js";
import { NotebookState } from "./notebook.js";
import { findNotebooks, type NotebookSession } from "./registry.js";
import type { Attachment } from "./render.js";
import { streamSession } from "./sse.js";
import { type PairTarget, sameServer } from "./touch.js";

export type Mode =
  | { kind: "auto" }
  | { kind: "pinned"; paths: string[] }
  | { kind: "off" };

export type Connection = "idle" | "searching" | "connecting" | "connected" | "disconnected";

export interface WatcherOptions {
  io: Io;
  cwd: string;
  token?: string;
  extraUrls?: string[];
  pollMs?: number;
  /** Most notebooks followed at once in auto mode. */
  maxNotebooks?: number;
  onChange: () => void;
}

type Target = NotebookSession & { real: string; shared: boolean };

const consumerId = (): string => `pi-marimo-${Math.random().toString(36).slice(2, 10)}`;

/** A followed notebook, as the hosts see it. */
export interface Followed {
  attachment: Attachment;
  notebook: NotebookState;
  connection: Connection;
  current: boolean;
  /** When this session's agent last worked in it (0: never). */
  touchedAt: number;
}

/** Read a saved or configured mode, accepting the single-notebook form `{ kind: "pinned", path }`. */
export function parseMode(raw: unknown): Mode | undefined {
  const mode = raw as { kind?: unknown; path?: unknown; paths?: unknown } | undefined;
  if (mode?.kind === "auto" || mode?.kind === "off") return { kind: mode.kind };
  if (mode?.kind !== "pinned") return undefined;
  const paths = Array.isArray(mode.paths) ? mode.paths.filter((p): p is string => typeof p === "string") : typeof mode.path === "string" ? [mode.path] : [];
  return paths.length ? { kind: "pinned", paths } : undefined;
}

/** One notebook's subscription, reconnecting until stopped. */
class Follower {
  readonly notebook = new NotebookState();
  connection: Connection = "connecting";
  /** Whether browser edits reach us (false when connected by the browser's own session id). */
  seesBrowserEdits = false;
  /** When this session's agent last worked in the notebook (0: never). */
  touchedAt = 0;
  private stopped = false;
  private current?: Cancellable<unknown>;
  private sleep?: Cancellable<void>;
  private readonly id = consumerId();
  readonly loop: Promise<void>;

  constructor(public target: Target, private readonly options: WatcherOptions, private readonly changed: () => void) {
    this.loop = this.run();
  }

  get attachment(): Attachment {
    return { url: this.target.url, sessionId: this.target.sessionId, path: this.target.path };
  }

  /** Point at a new session for the same file (a page reload) and reconnect. */
  retarget(target: Target): void {
    if (target.sessionId === this.target.sessionId && target.shared === this.target.shared) return;
    this.target = target;
    this.current?.cancel();
    this.sleep?.cancel();
  }

  stop(): void {
    this.stopped = true;
    this.current?.cancel();
    this.sleep?.cancel();
  }

  private set(connection: Connection): void {
    if (connection === this.connection) return;
    this.connection = connection;
    this.changed();
  }

  private async run(): Promise<void> {
    const pollMs = this.options.pollMs ?? 5000;
    while (!this.stopped) {
      const target = this.target;
      this.seesBrowserEdits = !target.shared;
      this.notebook.reset();
      this.set("connecting");
      const stream = streamSession({
        io: this.options.io,
        url: target.url,
        // marimo names a consumer after the session id it connected with and
        // does not echo a browser's own edits back to that id. Connecting
        // under our own id (marimo then finds the session by file) receives
        // them. That lookup takes the oldest session for the file, so when
        // several hold it, connect by the exact id and miss browser edits.
        sessionId: target.shared ? target.sessionId : this.id,
        file: target.path,
        token: this.options.token,
        onMessage: (op, data) => {
          const changed = this.notebook.apply(op, data);
          if (op === "kernel-ready") this.set("connected");
          if (changed) this.changed();
        },
      });
      this.current = stream;
      const result = await stream.done.catch(() => ({ kind: "http-error" as const }));
      if (this.stopped) break;
      this.set("disconnected");
      if (target !== this.target) continue;
      // A dropped stream reconnects quickly; a refused one waits for the next poll.
      this.sleep = this.options.io.sleep(result.kind === "ended" ? 1000 : pollMs);
      await this.sleep.done;
    }
  }
}

export class MarimoWatcher {
  mode: Mode = { kind: "auto" };
  private followers = new Map<string, Follower>();
  private stopped = true;
  private scanned = false;
  private wake?: () => void;
  private loop?: Promise<void>;
  private realCwd?: string;
  private readonly realPaths = new Map<string, string>();
  private readonly empty = new NotebookState();

  constructor(private readonly options: WatcherOptions) {}

  /** Followers, the current one first, then by most recent use. */
  private ranked(): Follower[] {
    const rank = (x: Follower): number[] => [x.connection === "connected" ? 1 : 0, x.touchedAt, x.notebook.running() ? 1 : 0, x.notebook.lastActivity];
    const cmp = (a: Follower, b: Follower): number => {
      const [x, y] = [rank(a), rank(b)];
      for (let i = 0; i < x.length; i++) if (x[i] !== y[i]) return y[i]! - x[i]!;
      return 0;
    };
    return [...this.followers.values()].sort(cmp);
  }

  /** The current notebook: the one used most recently. */
  private get active(): Follower | undefined {
    return this.ranked()[0];
  }

  /** Every followed notebook, the current one first, then by most recent use. */
  followed(): Followed[] {
    return this.ranked().map((f, i) => ({ attachment: f.attachment, notebook: f.notebook, connection: f.connection, current: i === 0, touchedAt: f.touchedAt }));
  }

  get notebook(): NotebookState {
    return this.active?.notebook ?? this.empty;
  }

  get attachment(): Attachment | undefined {
    const active = this.active;
    if (active) return active.attachment;
    return this.mode.kind === "pinned" ? { url: "", sessionId: "", path: this.mode.paths[0]! } : undefined;
  }

  get connection(): Connection {
    const active = this.active;
    if (active) return active.connection;
    return this.mode.kind === "off" ? "idle" : "searching";
  }

  get seesBrowserEdits(): boolean {
    return this.active?.seesBrowserEdits ?? false;
  }

  /**
   * The one followed notebook a marimo-pair call targets, if it is unambiguous: by session id, by
   * file (as marimo-pair takes it: absolute, or relative to the server's directory), or by server
   * alone when only one followed notebook is on it.
   */
  private match(t: PairTarget) {
    let matches = [...this.followers.values()];
    if (t.url) matches = matches.filter((f) => sameServer(f.target.url, t.url!));
    if (t.session) matches = matches.filter((f) => f.target.sessionId === t.session);
    else if (t.file) {
      const file = t.file.replace(/^\.\//, "");
      matches = matches.filter((f) => f.target.path === file || f.target.real === file || f.target.path.endsWith(`/${file}`) || f.target.real.endsWith(`/${file}`));
    } else if (!t.url) matches = [];
    return matches.length === 1 ? matches[0] : undefined;
  }

  /** The paths of the followed notebooks these marimo-pair calls target. */
  targeted(targets: PairTarget[]): string[] {
    return targets.map((t) => this.match(t)?.attachment.path).filter((p): p is string => p !== undefined);
  }

  /**
   * Note that this session's agent works in these notebooks (from its marimo-pair calls), making
   * the last one current for this session. Returns whether any followed notebook matched.
   */
  touch(targets: PairTarget[], now = Date.now()): boolean {
    let touched = false;
    targets.forEach((t, i) => {
      const match = this.match(t);
      if (!match) return;
      // Later calls in one tool call win.
      match.touchedAt = now + i;
      touched = true;
    });
    if (touched) this.options.onChange();
    return touched;
  }

  /** The other notebooks followed besides the current one, most recently used first. */
  others(): Attachment[] {
    return this.ranked().slice(1).map((f) => f.attachment);
  }

  start(): void {
    if (!this.stopped) return;
    this.stopped = false;
    this.loop = this.run();
  }

  /** Stop, waiting at most a second for streams to close (a host may only end one at its next chunk). */
  async stop(): Promise<void> {
    this.stopped = true;
    this.wake?.();
    const loops = [...this.followers.values()].map((f) => { f.stop(); return f.loop; });
    this.followers.clear();
    await Promise.race([Promise.all([this.loop, ...loops]).catch(() => undefined), this.options.io.sleep(1000).done]);
  }

  setMode(mode: Mode): void {
    this.mode = mode;
    this.scanned = false;
    this.wake?.();
  }

  /** Wait (up to ms) for the first scan and any connection in progress, so a first request has the state. */
  async settle(ms: number): Promise<void> {
    const busy = () => !this.scanned || [...this.followers.values()].some((f) => f.connection === "connecting");
    for (let waited = 0; !this.stopped && busy() && waited < ms; waited += 50) {
      await this.options.io.sleep(50).done;
    }
  }

  /** Rescan now instead of at the next poll. */
  refresh(): void {
    this.wake?.();
  }

  async list(): Promise<NotebookSession[]> {
    return findNotebooks(this.options.io, { token: this.options.token, extraUrls: this.options.extraUrls });
  }

  private async real(path: string): Promise<string> {
    const absolute = normalize(path, this.options.cwd);
    let real = this.realPaths.get(absolute);
    if (real === undefined) {
      real = normalize(await this.options.io.realpath(absolute));
      this.realPaths.set(absolute, real);
    }
    return real;
  }

  /** The notebooks to follow now, keyed by server and file. */
  private async targets(): Promise<Map<string, Target>> {
    const mode = this.mode;
    const out = new Map<string, Target>();
    if (mode.kind === "off") return out;
    const sessions = await this.list();
    const real = new Map<NotebookSession, string>();
    for (const s of sessions) real.set(s, await this.real(s.path));
    // Several sessions can hold one file (a closed tab's session lingers);
    // marimo lists them oldest first, so the newest wins.
    const add = (s: NotebookSession): void => {
      const path = real.get(s)!;
      const shared = sessions.filter((o) => o.url === s.url && real.get(o) === path).length > 1;
      out.set(`${s.url} ${path}`, { ...s, real: path, shared });
    };
    if (mode.kind === "pinned") {
      for (const pinned of mode.paths) {
        const path = await this.real(pinned);
        const chosen = sessions.filter((s) => real.get(s) === path).pop();
        if (chosen) add(chosen);
      }
      return out;
    }
    this.realCwd ??= await this.real(this.options.cwd);
    const cwd = this.realCwd;
    // Under the cwd, but not in a hidden directory there (.worktrees, .claude/worktrees: other checkouts).
    const local = sessions.filter((s) => {
      const path = real.get(s)!;
      return within(path, cwd) && !path.slice(cwd.length).split("/").slice(0, -1).some((part) => part.startsWith("."));
    });
    for (const s of local) add(s);
    const max = this.options.maxNotebooks ?? 8;
    return new Map([...out].slice(0, max));
  }

  private reconcile(targets: Map<string, Target>): void {
    let changed = false;
    for (const [key, follower] of this.followers) {
      if (targets.has(key)) continue;
      follower.stop();
      this.followers.delete(key);
      changed = true;
    }
    for (const [key, target] of targets) {
      const follower = this.followers.get(key);
      if (follower) follower.retarget(target);
      else {
        this.followers.set(key, new Follower(target, this.options, () => this.options.onChange()));
        changed = true;
      }
    }
    if (changed) this.options.onChange();
  }

  private async run(): Promise<void> {
    const pollMs = this.options.pollMs ?? 5000;
    while (!this.stopped) {
      const targets = await this.targets().catch(() => undefined);
      if (this.stopped) break;
      if (targets) this.reconcile(targets);
      if (!this.scanned) { this.scanned = true; this.options.onChange(); }
      const sleep = this.options.io.sleep(this.mode.kind === "off" ? 60_000 : pollMs);
      this.wake = sleep.cancel;
      await sleep.done;
    }
  }
}

files.hooks/core/notebook.ts:
// A notebook's live state, rebuilt from the messages marimo streams to its
// frontends: the cell document (kernel-ready, notebook-document-transaction),
// each cell's run state and errors (cell-op), and the dataflow graph
// (variables). Only what an agent needs is kept; outputs are dropped.

import { type Heading, headingsFromCode, isMarkdownCell, sameCode } from "./markdown.js";

export type EditSource = "frontend" | "code-mode" | "kernel" | string;

export interface Cell {
  id: string;
  code: string;
  name: string;
  disabled: boolean;
  /** "idle" | "queued" | "running" | "disabled-transitively" */
  status: string;
  /** When the current run started (ms since epoch), while running. */
  runningSince?: number;
  /** Inputs changed and the cell has not rerun (lazy runtime). */
  stale: boolean;
  /** One-line description of the error the cell's last run raised. */
  error?: string;
  /** The cell did not run because an ancestor failed. */
  blocked?: string;
  /** Code the kernel last ran for this cell, when known. */
  lastRunCode?: string;
  /** Who last changed the code, and at which change number. */
  editedBy?: EditSource;
  editSeq: number;
}

export interface RunningCell {
  cell: Cell;
  section: string[];
  since?: number;
}

const record = (value: unknown): Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
const strings = (value: unknown): string[] => Array.isArray(value) ? value.filter((v): v is string => typeof v === "string") : [];
const isInternal = (id: string): boolean => id.startsWith("__");

export function describeError(output: Record<string, unknown>): { error?: string; blocked?: string } {
  const errors = Array.isArray(output.data) ? output.data.map(record) : [];
  const parts: string[] = [];
  let blocked: string | undefined;
  for (const err of errors) {
    const type = typeof err.type === "string" ? err.type : "error";
    const msg = typeof err.msg === "string" ? err.msg.trim().split("\n")[0] : "";
    if (type === "ancestor-prevented" || type === "ancestor-stopped") {
      blocked = msg || "an ancestor cell failed";
      continue;
    }
    if (type === "exception") {
      const name = typeof err.exception_type === "string" ? err.exception_type : "Exception";
      parts.push(msg ? `${name}: ${msg}` : name);
    } else if (type === "multiple-defs") {
      const name = typeof err.name === "string" ? err.name : "?";
      parts.push(`multiple definitions of ${name}`);
    } else if (type === "interruption") {
      parts.push("interrupted");
    } else {
      parts.push(msg ? `${type}: ${msg}` : type);
    }
  }
  const error = parts.length ? truncate(parts.join("; "), 200) : undefined;
  return { error, blocked: error ? undefined : blocked };
}

export function truncate(text: string, max: number): string {
  return text.length <= max ? text : `${text.slice(0, max - 1)}…`;
}

export class NotebookState {
  order: string[] = [];
  cells = new Map<string, Cell>();
  defs = new Map<string, string[]>();
  ready = false;
  /** Increments on every document change. */
  seq = 0;
  /**
   * When the notebook was last used (ms since epoch): the latest cell run the
   * kernel reports (replayed on connect, so a notebook's history counts), or an
   * edit seen live.
   */
  lastActivity = 0;
  private readyAt = 0;
  private headingCache = new Map<string, Heading[]>();

  reset(): void {
    this.order = [];
    this.cells.clear();
    this.defs.clear();
    this.ready = false;
    this.lastActivity = 0;
    this.readyAt = 0;
    this.headingCache.clear();
  }

  private ensure(id: string): Cell {
    let cell = this.cells.get(id);
    if (!cell) {
      cell = { id, code: "", name: "_", disabled: false, status: "idle", stale: false, editSeq: 0 };
      this.cells.set(id, cell);
    }
    return cell;
  }

  headings(cell: Cell): Heading[] {
    let headings = this.headingCache.get(cell.code);
    if (!headings) {
      headings = headingsFromCode(cell.code);
      if (this.headingCache.size > 2000) this.headingCache.clear();
      this.headingCache.set(cell.code, headings);
    }
    return headings;
  }

  isMarkdown(cell: Cell): boolean {
    return isMarkdownCell(cell.code);
  }

  /** Apply one streamed message. Returns true when agent-visible state changed. */
  apply(op: string, raw: unknown): boolean {
    const data = record(raw);
    switch (op) {
      case "kernel-ready":
        return this.kernelReady(data);
      case "notebook-document-transaction":
        return this.transaction(record(data.transaction));
      case "cell-op":
        return this.cellOp(data);
      case "variables":
        return this.variables(data);
      default:
        return false;
    }
  }

  private kernelReady(data: Record<string, unknown>): boolean {
    this.reset();
    const ids = strings(data.cell_ids);
    const codes = strings(data.codes);
    const names = strings(data.names);
    const configs = Array.isArray(data.configs) ? data.configs.map(record) : [];
    const lastRun = record(data.last_executed_code);
    ids.forEach((id, i) => {
      const cell = this.ensure(id);
      cell.code = codes[i] ?? "";
      cell.name = names[i] || "_";
      cell.disabled = configs[i]?.disabled === true;
      if (typeof lastRun[id] === "string") cell.lastRunCode = lastRun[id] as string;
    });
    this.order = ids;
    this.ready = true;
    this.readyAt = Date.now();
    return true;
  }

  private place(id: string, before: unknown, after: unknown): void {
    this.order = this.order.filter((other) => other !== id);
    if (typeof before === "string" && this.order.includes(before)) {
      this.order.splice(this.order.indexOf(before), 0, id);
    } else if (typeof after === "string" && this.order.includes(after)) {
      this.order.splice(this.order.indexOf(after) + 1, 0, id);
    } else {
      this.order.push(id);
    }
  }

  private transaction(tx: Record<string, unknown>): boolean {
    const source = typeof tx.source === "string" ? tx.source : "unknown";
    const changes = Array.isArray(tx.changes) ? tx.changes.map(record) : [];
    let changed = false;
    for (const change of changes) {
      const id = typeof change.cellId === "string" ? change.cellId : "";
      switch (change.type) {
        case "create-cell": {
          const cell = this.ensure(id);
          cell.code = typeof change.code === "string" ? change.code : "";
          cell.name = typeof change.name === "string" && change.name ? change.name : "_";
          cell.disabled = record(change.config).disabled === true;
          cell.editedBy = source;
          cell.editSeq = ++this.seq;
          this.place(id, change.before, change.after);
          changed = true;
          break;
        }
        case "delete-cell":
          this.cells.delete(id);
          this.order = this.order.filter((other) => other !== id);
          this.defs.delete(id);
          this.seq++;
          changed = true;
          break;
        case "move-cell":
          this.place(id, change.before, change.after);
          this.seq++;
          changed = true;
          break;
        case "reorder-cells": {
          const ids = strings(change.cellIds).filter((cid) => this.cells.has(cid));
          const rest = this.order.filter((cid) => !ids.includes(cid));
          const next = [...ids, ...rest];
          if (next.join() !== this.order.join()) { this.order = next; this.seq++; changed = true; }
          break;
        }
        case "set-code": {
          const cell = this.ensure(id);
          const code = typeof change.code === "string" ? change.code : "";
          // The browser respelling a markdown cell is not an edit.
          if (cell.code !== code && sameCode(cell.code, code)) cell.code = code;
          else if (cell.code !== code) {
            cell.code = code;
            cell.editedBy = source;
            cell.editSeq = ++this.seq;
            changed = true;
          }
          break;
        }
        case "set-name": {
          const cell = this.ensure(id);
          cell.name = typeof change.name === "string" && change.name ? change.name : "_";
          changed = true;
          break;
        }
        case "set-config": {
          const cell = this.ensure(id);
          const disabled = change.disabled === true;
          if (cell.disabled !== disabled) { cell.disabled = disabled; changed = true; }
          break;
        }
      }
    }
    // An edit counts as use when it arrives live, not in the replay on connect.
    if (source !== "kernel" && changed && this.readyAt && Date.now() - this.readyAt > 1500) this.lastActivity = Date.now();
    return changed;
  }

  private cellOp(data: Record<string, unknown>): boolean {
    const id = typeof data.cell_id === "string" ? data.cell_id : "";
    if (!id || isInternal(id) || !this.cells.has(id)) return false;
    const cell = this.ensure(id);
    let changed = false;
    if (typeof data.status === "string" && typeof data.timestamp === "number") {
      this.lastActivity = Math.max(this.lastActivity, data.timestamp * 1000);
    }
    if (typeof data.status === "string" && data.status !== cell.status) {
      cell.status = data.status;
      if (data.status === "queued") {
        // The previous run's error is about to be replaced.
        cell.error = undefined;
        cell.blocked = undefined;
      }
      if (data.status === "running") {
        const at = typeof data.timestamp === "number" ? data.timestamp * 1000 : Date.now();
        cell.runningSince = at;
        cell.lastRunCode = cell.code;
        cell.error = undefined;
        cell.blocked = undefined;
        cell.stale = false;
      } else {
        cell.runningSince = undefined;
      }
      changed = true;
    }
    if (typeof data.stale_inputs === "boolean" && data.stale_inputs !== cell.stale) {
      cell.stale = data.stale_inputs;
      changed = true;
    }
    if (data.output !== null && typeof data.output === "object") {
      const output = record(data.output);
      const { error, blocked } = output.channel === "marimo-error" ? describeError(output) : {};
      if (error !== cell.error || blocked !== cell.blocked) {
        cell.error = error;
        cell.blocked = blocked;
        changed = true;
      }
    }
    return changed;
  }

  private variables(data: Record<string, unknown>): boolean {
    const vars = Array.isArray(data.variables) ? data.variables.map(record) : [];
    const defs = new Map<string, string[]>();
    for (const v of vars) {
      if (typeof v.name !== "string") continue;
      for (const id of strings(v.declared_by)) {
        if (!defs.has(id)) defs.set(id, []);
        defs.get(id)!.push(v.name);
      }
    }
    for (const names of defs.values()) names.sort();
    const before = JSON.stringify([...this.defs.entries()].sort());
    this.defs = defs;
    return before !== JSON.stringify([...defs.entries()].sort());
  }

  /** Cells in notebook order. */
  ordered(): Cell[] {
    return this.order.map((id) => this.cells.get(id)).filter((cell): cell is Cell => cell !== undefined);
  }

  /** The heading path ("Section", "Subsection") a cell sits under, including its own headings. */
  sectionPath(cellId: string): string[] {
    const stack: Heading[] = [];
    for (const cell of this.ordered()) {
      for (const heading of this.headings(cell)) {
        while (stack.length && stack[stack.length - 1]!.level >= heading.level) stack.pop();
        stack.push(heading);
      }
      if (cell.id === cellId) break;
    }
    return stack.map((h) => h.text);
  }

  running(): RunningCell | undefined {
    const cell = this.ordered().find((c) => c.status === "running");
    return cell ? { cell, section: this.sectionPath(cell.id), since: cell.runningSince } : undefined;
  }

  queued(): number {
    return this.ordered().filter((c) => c.status === "queued").length;
  }

  errors(): Cell[] {
    return this.ordered().filter((c) => c.error);
  }

  /** Code changed since the kernel last ran it (only known once a run was seen). */
  edited(cell: Cell): boolean {
    return cell.lastRunCode !== undefined && !sameCode(cell.lastRunCode, cell.code);
  }
}

